export const EmployeeDashboardView: React.FC = () => {
  const { engagements, currentUser, followUps, leaves } = useDashboardStore();
  const { setPageContext } = usePageContextStore();
  const [showLeaveModal, setShowLeaveModal] = React.useState(false);

{myTasks.slice(0, 10).map(t => (
  <div key={t.id} className="p-4 rounded-xl border border-slate-100 hover:border-slate-300 hover:shadow-sm transition-all group cursor-pointer bg-white">
    <div className="flex justify-between items-start mb-2">
      <h4 className="font-bold text-slate-800 text-sm group-hover:text-blue-600 transition-colors">{t.title}</h4>
      <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${
        t.priority === 'URGENT' ? 'bg-rose-100 text-rose-700' :
        t.priority === 'HIGH' ? 'bg-orange-100 text-orange-700' :
        'bg-slate-100 text-slate-600'
      }`}>
        {t.priority}
      </span>
    </div>
    <div className="flex items-center gap-4 text-xs text-slate-500">
      <span className="flex items-center gap-1 font-medium text-slate-700">
        <Briefcase size={12} /> {t.clientName}
      </span>
      {t.dueDate && (
        <span className={`flex items-center gap-1 ${new Date(t.dueDate) < now ? 'text-rose-600 font-bold' : ''}`}>
          <CalendarIcon size={12} /> 
          {new Date(t.dueDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
        </span>
      )}
    </div>
  </div>
))}

